<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class VoiceSession extends Model { use HasUuid; protected $fillable=['discord_bot_id','discord_guild_id','discord_channel_id','status','started_at','ended_at','last_activity_at','member_count','error_message']; protected function casts(): array{return ['started_at'=>'datetime','ended_at'=>'datetime','last_activity_at'=>'datetime','member_count'=>'integer'];} public function bot(): BelongsTo{return $this->belongsTo(DiscordBot::class,'discord_bot_id');} public function guild(): BelongsTo{return $this->belongsTo(DiscordGuild::class,'discord_guild_id');} public function channel(): BelongsTo{return $this->belongsTo(DiscordChannel::class,'discord_channel_id');} public function members(): HasMany{return $this->hasMany(VoiceSessionMember::class);} }
